(function(window,document){ function apenasNumeros(valor){return valor.replace(/\D/g,"");} function mascaraCPF(valor){return apenasNumeros(valor).slice(0,11).replace(/(\d{3})(\d)/,"$1.$2").replace(/(\d{3})(\d)/,"$1.$2").replace(/(\d{3})(\d{1,2})$/,"$1-$2");} function mascaraTelefone(valor){const numero=apenasNumeros(valor).slice(0,11);if(numero.length<=10)return numero.replace(/(\d{2})(\d)/,"($1) $2").replace(/(\d{4})(\d)/,"$1-$2");return numero.replace(/(\d{2})(\d)/,"($1) $2").replace(/(\d{5})(\d)/,"$1-$2");} function mascaraCEP(valor){return apenasNumeros(valor).slice(0,8).replace(/(\d{5})(\d)/,"$1-$2");} function atualizarAria(form){form.querySelectorAll("input,select").forEach(function(campo){campo.setAttribute("aria-invalid",campo.checkValidity()?"false":"true");});} function restaurarCadastro(form){const dados=window.PontoDignoStorage.carregarCadastro();if(!dados)return;if(form.elements.nome)form.elements.nome.value=dados.nome||"";if(form.elements.email)form.elements.email.value=dados.email||"";if(form.elements.telefone)form.elements.telefone.value=dados.telefone||"";if(dados.participacao){const opcao=form.querySelector('input[name="participacao"][value="'+dados.participacao+'"]');if(opcao)opcao.checked=true;}} function configurarFormulario(){const form=document.querySelector("#form-cadastro");if(!form||form.dataset.bound==="true")return;form.dataset.bound="true";const mensagem=form.querySelector("#mensagem-form");const cpf=form.querySelector("#cpf");const telefone=form.querySelector("#telefone");const cep=form.querySelector("#cep");if(cpf)cpf.addEventListener("input",function(e){e.target.value=mascaraCPF(e.target.value);e.target.setAttribute("aria-invalid",e.target.checkValidity()?"false":"true");});if(telefone)telefone.addEventListener("input",function(e){e.target.value=mascaraTelefone(e.target.value);e.target.setAttribute("aria-invalid",e.target.checkValidity()?"false":"true");});if(cep)cep.addEventListener("input",function(e){e.target.value=mascaraCEP(e.target.value);e.target.setAttribute("aria-invalid",e.target.checkValidity()?"false":"true");});form.addEventListener("input",function(e){if(e.target.matches("input,select"))e.target.setAttribute("aria-invalid",e.target.checkValidity()?"false":"true");});form.addEventListener("change",function(e){if(e.target.matches("input,select"))e.target.setAttribute("aria-invalid",e.target.checkValidity()?"false":"true");});form.addEventListener("submit",function(event){event.preventDefault();atualizarAria(form);if(!form.checkValidity()){mensagem.textContent="Confira os campos destacados antes de enviar.";mensagem.className="mensagem";form.reportValidity();window.PontoDignoUI.mostrarToast("Existem campos que precisam de correção.");return;}const dados={participacao:form.elements.participacao.value,nome:form.elements.nome.value,email:form.elements.email.value,telefone:form.elements.telefone.value};window.PontoDignoStorage.salvarCadastro(dados);mensagem.textContent="Cadastro demonstrativo salvo no navegador.";mensagem.className="mensagem sucesso";window.PontoDignoUI.mostrarToast("Cadastro salvo com sucesso.");});restaurarCadastro(form);atualizarAria(form);} window.PontoDignoFormulario={configurarFormulario,mascaraCPF,mascaraTelefone,mascaraCEP}; })(window,document);